.cr_st_scenarios<-function(contract,origin,context){
 c<-contract;.cr_data_required(c,c('contract_id','version','scenario_ids','weights','dates','currency','probability_measure','sampling_design','conditioning'));for(key in c('contract_id','version','currency','conditioning')) .cr_sc_text(c[[key]],key);for(key in c('scenario_ids','dates'))if(!length(c[[key]])||anyDuplicated(unlist(c[[key]],use.names=FALSE))) .cr_error('STRUCTURED_SCENARIOS','Unique nonempty scenario/date axes required');for(sid in c$scenario_ids) .cr_sc_text(sid,'scenario_id');previous<-origin;for(date in c$dates){if(.cr_data_date(date,'date')<=.cr_data_date(previous,'previous')) .cr_error('STRUCTURED_CALENDAR','Risk grid must increase after origin');previous<-date};if(length(c$weights)!=length(c$scenario_ids)) .cr_error('STRUCTURED_SCENARIOS','Aligned weights required');weights<-vapply(c$weights,function(w).cr_sc_number(w,'weight',0),0.);if(abs(.cr_sc_sum(weights)-1)>1e-12||c$probability_measure!='PHYSICAL'||!(c$sampling_design%in%c('IID_UNWEIGHTED','FIXED_WEIGHTED_SCENARIOS','DEPENDENT_OR_QMC'))) .cr_error('STRUCTURED_SCENARIOS','Normalized physical scenario contract required');if(c$sampling_design=='IID_UNWEIGHTED'&&any(abs(weights-1/length(weights))>1e-14)) .cr_error('STRUCTURED_SCENARIOS','IID requires equal weights');ctx<-.cr_result(NULL,'structured.context',context=context)$context;expected<-list(currency=c$currency,probability_measure='PHYSICAL',conditioning=c$conditioning,time_unit='days',horizon=as.numeric(.cr_data_date(tail(c$dates,1)[[1]],'date')-.cr_data_date(origin,'origin')));if(any(vapply(names(expected),function(k)!is.null(ctx[[k]])&&!identical(as.character(ctx[[k]]),as.character(expected[[k]])),TRUE))) .cr_error('TARGET_MISMATCH','Physical scenario and actual day horizon must agree with context');list(contract=c,context=ctx)
}
.cr_st_party_events<-function(contract,mapping,required_parties,group_paths,innovations){
 party_map<-list();for(row in .cr_data_rows(mapping,'party_mapping')){.cr_data_required(row,c('party_id','default_group_id'));party<-.cr_sc_text(row$party_id,'party_id');group<-.cr_sc_text(row$default_group_id,'default_group_id');if(!is.null(party_map[[party]])) .cr_error('STRUCTURED_DEFAULT_GROUP','A legal party must have one shared default group across roles');party_map[[party]]<-group};if(!setequal(names(party_map),required_parties)) .cr_error('STRUCTURED_DEFAULT_GROUP','Exact participating-party mapping required');groups<-unique(unlist(party_map,use.names=FALSE));sids<-unlist(contract$scenario_ids,use.names=FALSE);dates<-unlist(contract$dates,use.names=FALSE);imap<-gp<-list();used<-character();keyfn<-function(...).cr_hash(list(...))
 for(row in .cr_data_rows(innovations,'shared_innovations')){.cr_data_required(row,c('scenario_id','date','channel_id','uniform'));key<-keyfn(row$scenario_id,row$date,.cr_sc_text(row$channel_id,'channel_id'));u<-.cr_sc_number(row$uniform,'uniform',0,1);if(!is.null(imap[[key]])||!(row$scenario_id%in%sids)||!(row$date%in%dates)||u==1) .cr_error('STRUCTURED_INNOVATION','Unique aligned uniforms in [0,1) required');imap[[key]]<-u}
 for(row in .cr_data_rows(group_paths,'party_default_paths')){.cr_data_required(row,c('scenario_id','default_group_id','date','conditional_pd','default_channel'));key<-keyfn(row$scenario_id,row$default_group_id,row$date);ik<-keyfn(row$scenario_id,row$date,row$default_channel);if(!is.null(gp[[key]])||!(row$scenario_id%in%sids)||!(row$default_group_id%in%groups)||!(row$date%in%dates)) .cr_error('STRUCTURED_DEFAULT_GROUP','Aligned unique group hazard grid required');.cr_sc_number(row$conditional_pd,'conditional_pd',0,1);if(is.null(imap[[ik]])) .cr_error('STRUCTURED_INNOVATION','Missing group innovation');gp[[key]]<-row;used<-union(used,ik)}
 expected<-character();for(s in sids)for(g in groups)for(d in dates)expected<-c(expected,keyfn(s,g,d));if(!setequal(names(gp),expected)||!setequal(used,names(imap))) .cr_error('STRUCTURED_DEFAULT_GROUP','Complete group grid and exactly used innovations required');defaults<-events<-list()
 for(sid in sids)for(group in sort(groups)){first<-NULL;for(date in dates){row<-gp[[keyfn(sid,group,date)]];new<-is.null(first)&&imap[[keyfn(sid,date,row$default_channel)]]<row$conditional_pd;if(new)first<-date;events[[length(events)+1L]]<-list(scenario_id=sid,default_group_id=group,date=date,new_default=new,in_default=!is.null(first))};defaults[keyfn(sid,group)]<-list(first)};list(party_map=party_map,defaults=defaults,events=events)
}
simulate_trade_receivables<-function(invoice_pool,scenario_contract,party_mapping,party_default_paths,invoice_scenarios,seller_terms,servicer_terms,shared_innovations,context=NULL){
 pool<-.cr_sc_checked(invoice_pool,'CreditAssetPool');parsed<-.cr_st_scenarios(scenario_contract,pool$as_of,context);contract<-parsed$contract;ctx<-parsed$context;if(pool$profile$product_kind!='TRADE_RECEIVABLES'||pool$profile$pool_mode!='STATIC'||contract$currency!=pool$profile$currency) .cr_error('STRUCTURED_ROUTE','Static observed invoice pool and matching currency required');origin<-pool$as_of;horizon<-tail(contract$dates,1)[[1]];shares<-tape<-list();keyfn<-function(...).cr_hash(list(...))
 for(rec in pool$active_assignments){a<-rec$assignment;aid<-a$asset_id;if(!is.null(a$effective_until)&&a$effective_until<=horizon) .cr_error('STRUCTURED_TRANSFER','Invoice assignment must remain effective through horizon');shares[[aid]]<-.cr_sc_sum(c(if(is.null(shares[[aid]]))0 else shares[[aid]],a$share));tape[[aid]]<-pool$asset_contracts[[aid]]};if(!length(tape)) .cr_error('STRUCTURED_TRADE','Nonempty owned invoice pool required');for(a in tape)if(a$asset_class!='INVOICE'||length(a$schedule)!=1L||a$schedule[[1]]$interest_due!=0) .cr_error('STRUCTURED_TRADE','One zero-interest bullet per invoice required');parties<-unique(unlist(lapply(tape,function(a)c(a$obligor_id,a$seller_id,a$servicer_id)),use.names=FALSE));ev<-.cr_st_party_events(contract,party_mapping,parties,party_default_paths,shared_innovations);party_map<-ev$party_map;defaults<-ev$defaults;events<-ev$events;if(any(vapply(tape,function(a)party_map[[a$obligor_id]]!=a$default_group_id,TRUE))) .cr_error('STRUCTURED_DEFAULT_GROUP','Debtor mapping must match frozen pool group')
 date_in<-function(value,name){if(!(.cr_data_date(origin,'origin')<=.cr_data_date(value,name)&&.cr_data_date(value,name)<=.cr_data_date(horizon,'horizon'))) .cr_error('STRUCTURED_CALENDAR','All modeled cash/event dates must fit explicit horizon');value};sids<-unlist(contract$scenario_ids,use.names=FALSE);scenarios<-list()
 for(row in .cr_data_rows(invoice_scenarios,'invoice_scenarios')){.cr_data_required(row,c('scenario_id','asset_id','payment_date','dilution_date','dilution_fraction','debtor_recovery_fraction','debtor_recovery_date','debtor_recovery_cost'));key<-keyfn(row$scenario_id,row$asset_id);if(!is.null(scenarios[[key]])||!(row$scenario_id%in%sids)||!(row$asset_id%in%names(tape))) .cr_error('STRUCTURED_TRADE','Unique aligned invoice scenarios required');for(k in c('payment_date','dilution_date','debtor_recovery_date'))date_in(row[[k]],k);for(k in c('dilution_fraction','debtor_recovery_fraction')) .cr_sc_number(row[[k]],k,0,1);.cr_sc_number(row$debtor_recovery_cost,'debtor_recovery_cost',0);a<-tape[[row$asset_id]];default<-defaults[[keyfn(row$scenario_id,a$default_group_id)]];if(row$payment_date<a$schedule[[1]]$date) .cr_error('STRUCTURED_CALENDAR','Invoice early settlement needs explicit discount terms; payment cannot precede due date');event_date<-if(is.null(default))row$payment_date else min(row$payment_date,default);if(row$dilution_date>event_date||row$debtor_recovery_date<event_date) .cr_error('STRUCTURED_CALENDAR','Dilution must precede payment/default; recovery cannot precede event');scenarios[[key]]<-row}
 expected<-character();for(s in sids)for(a in names(tape))expected<-c(expected,keyfn(s,a));if(!setequal(names(scenarios),expected)) .cr_error('STRUCTURED_TRADE','Full invoice/scenario grid required');sellers<-unique(vapply(tape,function(a)a$seller_id,''));servicers<-unique(vapply(tape,function(a)a$servicer_id,''));seller_map<-servicer_map<-list()
 for(kind in c('seller','servicer')){rows<-if(kind=='seller')seller_terms else servicer_terms;ids<-if(kind=='seller')sellers else servicers;dest<-list();for(row in .cr_data_rows(rows,paste0(kind,'_terms'))){idkey<-paste0(kind,'_id');.cr_data_required(row,c('scenario_id',idkey));key<-keyfn(row$scenario_id,row[[idkey]]);if(!is.null(dest[[key]])||!(row$scenario_id%in%sids)||!(row[[idkey]]%in%ids)) .cr_error('STRUCTURED_TRADE','Unique aligned seller/servicer terms required');if(kind=='seller'){.cr_data_required(row,c('settlement_date','performing_capacity','default_estate_capacity','default_recovery_fraction','recourse_scope'));date_in(row$settlement_date,'settlement_date');for(k in c('performing_capacity','default_estate_capacity')) .cr_sc_number(row[[k]],k,0);.cr_sc_number(row$default_recovery_fraction,'default_recovery_fraction',0,1);if(!(row$recourse_scope%in%c('CREDIT_ONLY','CREDIT_AND_DILUTION'))) .cr_error('STRUCTURED_TRADE','Explicit seller recourse scope required')}else{.cr_data_required(row,c('remittance_date','default_commingling_recovery_fraction','default_commingling_capacity','replacement_cost'));date_in(row$remittance_date,'remittance_date');.cr_sc_number(row$default_commingling_recovery_fraction,'default_commingling_recovery_fraction',0,1);for(k in c('default_commingling_capacity','replacement_cost')) .cr_sc_number(row[[k]],k,0)};dest[[key]]<-row};expected<-character();for(s in sids)for(i in ids)expected<-c(expected,keyfn(s,i));if(!setequal(names(dest),expected)) .cr_error('STRUCTURED_TRADE','Full seller/servicer scenario terms required');if(kind=='seller')seller_map<-dest else servicer_map<-dest}
 invoice_results<-seller_results<-servicer_results<-cashflows<-ending<-list();cash<-function(sid,date,source,party,amount,asset_id=NULL){cashflows[[length(cashflows)+1L]]<<-list(scenario_id=sid,date=date,source=source,party_id=party,asset_id=asset_id,amount=.cr_sc_sum(amount))}
 for(sid in sids){claims<-list();collections<-setNames(rep(list(list()),length(servicers)),servicers);costs<-numeric()
 for(aid in sort(names(tape))){a<-tape[[aid]];row<-scenarios[[keyfn(sid,aid)]];amount<-a$principal_balance*shares[[aid]];dilution<-amount*row$dilution_fraction;net<-amount-dilution;default<-defaults[[keyfn(sid,a$default_group_id)]];credit_event<-net>0&&!is.null(default)&&default<=row$payment_date;received<-if(credit_event)net*row$debtor_recovery_fraction else net;collection_date<-if(credit_event)row$debtor_recovery_date else row$payment_date;cost<-if(credit_event)row$debtor_recovery_cost*shares[[aid]]else 0;if(seller_map[[keyfn(sid,a$seller_id)]]$settlement_date<collection_date||servicer_map[[keyfn(sid,a$servicer_id)]]$remittance_date<collection_date) .cr_error('STRUCTURED_CALENDAR','Seller residual settlement and servicer remittance must follow debtor cash');claims[[aid]]<-list(scenario_id=sid,asset_id=aid,invoice_id=a$invoice_id,owned_principal=amount,dilution_loss=dilution,debtor_credit_event=credit_event,debtor_default_date=default,actual_collection_date=collection_date,debtor_collection=received,debtor_credit_loss=net-received,seller_credit_recourse=0,seller_dilution_recourse=0,debtor_recovery_cost=cost);collections[[a$servicer_id]][[length(collections[[a$servicer_id]])+1L]]<-list(aid=aid,date=collection_date,amount=received);costs<-c(costs,cost);if(cost!=0)cash(sid,collection_date,'DEBTOR_WORKOUT_COST',a$obligor_id,-cost,aid)}
 for(seller in sort(sellers)){term<-seller_map[[keyfn(sid,seller)]];default<-defaults[[keyfn(sid,party_map[[seller]])]];failed<-!is.null(default)&&default<=term$settlement_date;eligible<-list();for(aid in names(tape)){a<-tape[[aid]];if(a$seller_id==seller&&a$recourse=='SELLER'){q<-claims[[aid]];eligible[[aid]]<-.cr_sc_sum(c(q$debtor_credit_loss,if(term$recourse_scope=='CREDIT_AND_DILUTION')q$dilution_loss else 0))}};total<-.cr_sc_sum(unlist(eligible,use.names=FALSE));payment<-min(total*(if(failed)term$default_recovery_fraction else 1),if(failed)term$default_estate_capacity else term$performing_capacity);allocated<-numeric();for(aid in sort(names(eligible))){claim<-eligible[[aid]];take<-if(total>0)payment*(claim/total)else 0;q<-claims[[aid]];credit<-if(claim>0)take*(q$debtor_credit_loss/claim)else 0;q$seller_credit_recourse<-credit;q$seller_dilution_recourse<-take-credit;claims[[aid]]<-q;allocated<-c(allocated,take);if(take!=0)cash(sid,term$settlement_date,'SELLER_RECOURSE',seller,take,aid)};seller_results[[length(seller_results)+1L]]<-list(scenario_id=sid,seller_id=seller,in_default=failed,eligible_claim=total,aggregate_payment=.cr_sc_sum(allocated),capacity_used=.cr_sc_sum(allocated),settlement_date=term$settlement_date)}
 commingling_total<-replacement_total<-0
 for(servicer in sort(servicers)){term<-servicer_map[[keyfn(sid,servicer)]];default<-defaults[[keyfn(sid,party_map[[servicer]])]];failed<-!is.null(default)&&default<=term$remittance_date;held<-list();redirected<-0;for(rec in collections[[servicer]]){if(failed&&rec$date>=default){if(rec$amount!=0)cash(sid,rec$date,'REDIRECTED_DEBTOR_COLLECTION',servicer,rec$amount,rec$aid);redirected<-.cr_sc_sum(c(redirected,rec$amount))}else held[[length(held)+1L]]<-rec};held_total<-.cr_sc_sum(vapply(held,function(x)x$amount,0.));remitted<-if(failed)min(held_total*term$default_commingling_recovery_fraction,term$default_commingling_capacity)else held_total;if(remitted!=0)cash(sid,term$remittance_date,'SERVICER_REMITTANCE',servicer,remitted);replacement<-if(failed)term$replacement_cost else 0;if(replacement!=0)cash(sid,default,'SERVICER_REPLACEMENT_COST',servicer,-replacement);lost<-held_total-remitted;commingling_total<-.cr_sc_sum(c(commingling_total,lost));replacement_total<-.cr_sc_sum(c(replacement_total,replacement));servicer_results[[length(servicer_results)+1L]]<-list(scenario_id=sid,servicer_id=servicer,in_default_before_remittance=failed,held_cash=held_total,redirected_cash=redirected,remittance=remitted,commingling_loss=lost,replacement_cost=replacement)}
 invoice_results<-c(invoice_results,unname(claims));net_credit<-.cr_sc_sum(vapply(claims,function(q)q$debtor_credit_loss-q$seller_credit_recourse,0.));net_dilution<-.cr_sc_sum(vapply(claims,function(q)q$dilution_loss-q$seller_dilution_recourse,0.));net_cash<-.cr_sc_sum(vapply(Filter(function(r)r$scenario_id==sid,cashflows),function(r)r$amount,0.));total_principal<-.cr_sc_sum(vapply(claims,function(q)q$owned_principal,0.));total_cost<-.cr_sc_sum(c(costs,replacement_total));residual<-.cr_sc_sum(c(total_principal,-net_credit,-net_dilution,-commingling_total,-total_cost,-net_cash));if(abs(residual)>1e-10*max(1,total_principal)) .cr_error('STRUCTURED_CONSERVATION','Invoice principal/recourse/operational cash reconciliation failed');ending[[length(ending)+1L]]<-list(scenario_id=sid,owned_principal=total_principal,net_credit_loss=net_credit,net_dilution_loss=net_dilution,commingling_loss=commingling_total,workout_and_replacement_cost=total_cost,net_investor_cash=net_cash,conservation_residual=residual)
 }
 if(length(cashflows))cashflows<-cashflows[order(vapply(cashflows,function(r)r$scenario_id,''),vapply(cashflows,function(r)r$date,''),vapply(cashflows,function(r)r$source,''),vapply(cashflows,function(r)r$party_id,''),vapply(cashflows,function(r)if(is.null(r$asset_id))''else r$asset_id,''))]
 value<-.cr_sc_bound(list(schema_version='1.0',kind='TradeReceivablePaths',pool_hash=pool$sha256,scenario_contract=contract,innovation_hash=.cr_hash(shared_innovations),party_mapping=party_mapping,input_hash=.cr_hash(list(party_default_paths=party_default_paths,invoice_scenarios=invoice_scenarios,seller_terms=seller_terms,servicer_terms=servicer_terms)),group_events=events,invoice_results=invoice_results,seller_results=seller_results,servicer_results=servicer_results,cashflows=cashflows,ending_states=ending))
 .cr_result(value,'structured_credit.simulate_trade_receivables','invoice_cashflows',ctx,diagnostics=.cr_empty_object(),limitations='Observed static bullet invoices only; actual delayed payment remains exposed to shared debtor default until payment, with default before same-day payment. A legal party has one shared default group across debtor, seller and servicer roles. Commercial dilution precedes credit/payment and remains separate; full dilution creates no debtor workout cost. Residual seller recourse follows debtor recoveries, is capped once across invoices and allocated pro rata; it is paid directly to investor outside servicer accounts. Before-failure collections held by the servicer share one capped commingling claim; on/after-failure collections redirect directly, and replacement cost is charged once. All event and cash dates must fit the explicit horizon; unresolved or future-originated claims are not silently completed.')
}
